window.ScripturaLexicons.BDAG_PART_0331 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0331-01\" data-source=\"BDAG\" data-search=\"στενός, ή, όν adjetivo estreito BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στενός, ή, όν</td><td>adjetivo</td><td>estreito</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0331-02\" data-source=\"BDAG\" data-search=\"στενοχωρέω verbo confinar; angustiar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στενοχωρέω</td><td>verbo</td><td>confinar; angustiar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0331-03\" data-source=\"BDAG\" data-search=\"στενοχωρία, ας, ἡ substantivo feminino angústia; tribulação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στενοχωρία, ας, ἡ</td><td>substantivo feminino</td><td>angústia; tribulação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0331-04\" data-source=\"BDAG\" data-search=\"στέργω verbo amar; sentir afeição BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στέργω</td><td>verbo</td><td>amar; sentir afeição</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0331-05\" data-source=\"BDAG\" data-search=\"στερεός, ά, όν adjetivo firme; sólido BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στερεός, ά, όν</td><td>adjetivo</td><td>firme; sólido</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0331-06\" data-source=\"BDAG\" data-search=\"στερεόω verbo fortalecer; consolidar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στερεόω</td><td>verbo</td><td>fortalecer; consolidar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0331-07\" data-source=\"BDAG\" data-search=\"στερέω verbo privar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στερέω</td><td>verbo</td><td>privar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0331-08\" data-source=\"BDAG\" data-search=\"στερέωμα, ατος, τό substantivo neutro firmamento; firmeza BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στερέωμα, ατος, τό</td><td>substantivo neutro</td><td>firmamento; firmeza</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0331-09\" data-source=\"BDAG\" data-search=\"Στεφανᾶς, ᾶ, ὁ substantivo masculino; nome próprio Estéfanas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Στεφανᾶς, ᾶ, ὁ</td><td>substantivo masculino; nome próprio</td><td>Estéfanas</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0331-10\" data-source=\"BDAG\" data-search=\"Στέφανος, ου, ὁ substantivo masculino; nome próprio Estêvão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Στέφανος, ου, ὁ</td><td>substantivo masculino; nome próprio</td><td>Estêvão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0331-11\" data-source=\"BDAG\" data-search=\"στέφανος, ου, ὁ substantivo masculino coroa; grinalda; recompensa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στέφανος, ου, ὁ</td><td>substantivo masculino</td><td>coroa; grinalda; recompensa</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0331-12\" data-source=\"BDAG\" data-search=\"στεφανόω verbo coroar; recompensar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στεφανόω</td><td>verbo</td><td>coroar; recompensar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0331-13\" data-source=\"BDAG\" data-search=\"στῆθος, ους, τό substantivo neutro peito; tórax BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στῆθος, ους, τό</td><td>substantivo neutro</td><td>peito; tórax</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0331-14\" data-source=\"BDAG\" data-search=\"στήκω verbo estar de pé; permanecer firme BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στήκω</td><td>verbo</td><td>estar de pé; permanecer firme</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0331-15\" data-source=\"BDAG\" data-search=\"στήλη, ης, ἡ substantivo feminino coluna; monumento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στήλη, ης, ἡ</td><td>substantivo feminino</td><td>coluna; monumento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0331-16\" data-source=\"BDAG\" data-search=\"στηριγμός, οῦ, ὁ substantivo masculino segurança; firmeza BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στηριγμός, οῦ, ὁ</td><td>substantivo masculino</td><td>segurança; firmeza</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0331-17\" data-source=\"BDAG\" data-search=\"στηρίζω verbo estabelecer; fortalecer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στηρίζω</td><td>verbo</td><td>estabelecer; fortalecer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0331-18\" data-source=\"BDAG\" data-search=\"στιβάζω verbo armazenar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στιβάζω</td><td>verbo</td><td>armazenar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0331-19\" data-source=\"BDAG\" data-search=\"στιβαρός, ά, όν adjetivo robusto; vigoroso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στιβαρός, ά, όν</td><td>adjetivo</td><td>robusto; vigoroso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0331-20\" data-source=\"BDAG\" data-search=\"στιβάς, άδος, ἡ substantivo feminino folhas; ramos folhosos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">στιβάς, άδος, ἡ</td><td>substantivo feminino</td><td>folhas; ramos folhosos</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0331-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στενός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στενός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (Aeschyl., Hdt.+; ins, pap, LXX; TestAbr; EpArist 118; Philo; Jos., Bell. 1, 41; Mel., P. 45, 317), com referência à dimensão, estreito. <span class=\"greek\">πύλη</span> (ver o verbete, acepção 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:13f.</a> <span class=\"greek\">θύρα</span> (Arrian, Anab. 6, 29, 5, acerca da <span class=\"greek\">θυρὶς</span> <span class=\"greek\">στενή</span> no túmulo de Ciro, <span class=\"greek\">ὡς</span> <span class=\"greek\">μόλις</span> <span class=\"greek\">ἂν</span> <span class=\"greek\">εἶναι</span> <span class=\"greek\">ἑνὶ</span> <span class=\"greek\">ἀνδρὶ</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">μεγάλῳ</span> <span class=\"greek\">πολλὰ</span> <span class=\"greek\">κακοπαθοῦντι</span> <span class=\"greek\">παρελθεῖν</span> = de modo que até um homem relativamente pequeno teria dificuldade para passar sem algum sofrimento) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:24</a>. Acerca de uma cela de prisão, AcPl Ha 3, 19 (texto restaurado). <span class=\"greek\">στ</span>. <span class=\"greek\">ὁδός</span> (Machon v. 392; Nicol. Dam.: 90 Fgm. 66, 38 Jac.; Diod S 20, 29, 7; Maximus Tyr. 39, 3n <span class=\"greek\">μία</span> [<span class=\"greek\">ὁδὸς</span>] <span class=\"greek\">στενὴ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τραχεῖα</span> <span class=\"greek\">κ</span>. <span class=\"greek\">οὐ</span> <span class=\"greek\">πολλοῖς</span> <span class=\"greek\">πάνυ</span> <span class=\"greek\">ὁδεύσιμος</span> = um caminho estreito e áspero, dificilmente transitável por um grupo numeroso; Appian, Syr. 43 §225; Arrian, Anab. 2, 11, 3; 3, 18, 4; Jos., Ant. 19, 116) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:14</a>, variante de leitura.—B. 886. DELG. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0331-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στενοχωρέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στενοχωρέω</span> (<span class=\"greek\">στενός</span>, <span class=\"greek\">χῶρος</span> ‘espaço’), 1 aoristo, 3 pessoa do singular <span class=\"greek\">ἐστενοχώρησεν</span> Judg 16:16 B (desde Machon [século III a.C.], v. 396; pap, embora intransitivo).</p><p class=\"entry-text\">① encerrar ou restringir em espaço estreito, comprimir, apertar, confinar, restringir (Diod S 20, 29, 7; Lucian, Nigr. 13, Tox. 29 al.; LXX); figuradamente, na voz passiva, estar confinado, restringido (Herm. Wr. 2, 11; escólio a Eur., Med. 57 <span class=\"greek\">στενοχωρεῖσθαι</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κακῷ</span>; Is 28:20; Jos., Bell. 4, 163). <span class=\"greek\">οὐ</span> <span class=\"greek\">στενοχωρεῖσθε</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἡμῖν</span>, <span class=\"greek\">στενοχωρεῖσθε</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">σπλάγχνοις</span> <span class=\"greek\">ὑμῶν</span>, não estais restringidos em nós (isto é, não estais encerrados numa região estreita do afeto de Paulo; ver v. 11), mas, antes, em vosso próprio coração, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 6:12</a>.</p><p class=\"entry-text\">② encontrar-se em circunstâncias que parecem não oferecer saída, estar angustiado, extensão figurada de 1, na voz passiva, como grau mais intenso em comparação com <span class=\"greek\">θλίβεσθαι</span> (Epict. 1, 25, 28): <span class=\"greek\">θλιβόμενοι</span> <span class=\"greek\">ἀλλ</span>’ <span class=\"greek\">οὐ</span> <span class=\"greek\">στενοχωρούμενοι</span>, pressionados, mas não angustiados/esmagados, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 4:8</a>. Em sentido ativo, acerca do Espírito Santo, quando a ira toma conta de uma pessoa em quem ele habita: <span class=\"greek\">στενοχωρεῖται</span>, ele se angustia, Hm 5, 1, 3. Acerca das tribulações que os servos de Deus, em contraste com os injustos, devem suportar, 2 Cl 20:1.—DELG s.v. <span class=\"greek\">στενός</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0331-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στενοχωρία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στενοχωρία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (ver o verbete anterior; no sentido literal, ‘estreiteza’, Thu. e outros), figuradamente, conjunto de circunstâncias estressantes, aflição, dificuldade, angústia, tribulação (Polyb. 1, 67, 1; Petosiris, Fgm. 7 ln. 22 [com <span class=\"greek\">πόλεμος</span>]; Plut., Mor. 182b; Artem. 3, 14; Aelian, VH 2, 41; Cass. Dio 39, 34; PCairZen 435, 2 [século III a.C.]; Cat. Cod. Astr. VII 169, 21; Sir 10:26; 1 Macc 2:53; 3 Macc 2:10; En 98:10; TestAbr B 7 p. 111, 21 [Stone p. 70]) com <span class=\"greek\">θλῖψις</span> (Artem. 1, 68; 82; 2, 3 al.; Dt 28:53; 55; 57; Is 8:22; 30:6; Esth 1:1g; PLond V, 1677, 11 [século VI d.C.]. Cf. Epict. 1, 25, 26 <span class=\"greek\">στενοχωρία</span> … <span class=\"greek\">θλίβειν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:9</a>; 8:35. Com <span class=\"greek\">λύπη</span> Hv 4, 3, 4; m 10, 2, 6. No plural, dificuldades (frequentemente em Artem.; 1 Macc 13:3; Cat. Cod. Astr. VIII/1 p. 165, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 6:4</a>; 12:10.—DELG s.v. <span class=\"greek\">στενός</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0331-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στέργω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στέργω</span> (Aeschyl., Hdt.+; ins, pap; Sir 27:17; Philo; Jos., Bell. 1, 596, Ant. 8, 249; SibOr 4, 25; Just., Ath.; raramente empregado para expressão sexual) ter interesse benevolente ou solicitude por, amar, sentir afeição por <span class=\"greek\">τινά</span>, alguém; acerca do amor da esposa pelo marido (Theocr. 17, 130; IAndrosIsis, Kyme 27f; cf. Menand., PDidot I, 14f p. 329 S.: acerca de <span class=\"greek\">νόμος</span> aplicável ao marido e à esposa) 1 Cl 1:3; Pol 4:2. BWarfield, The Terminology of Love in the NT: PTR 16, 1918, 1–45; 153–203.—B. 1110. DELG. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0331-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στερεός, ά, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στερεός</span>, <span class=\"greek\">ά</span>, <span class=\"greek\">όν</span> (Hom. e outros; ins, pap, LXX, En, EpArist, Philo, Joseph., Just., D. 5, 2).</p><p class=\"entry-text\">① relativo a ser firme ou sólido, em contraste com o que é macio ou viscoso, firme, duro, sólido, forte. <span class=\"greek\">θεμέλιος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:19</a>. <span class=\"greek\">πέτρα</span> (PPetr II, 4, 1, 3 [século III a.C.]; LXX; En 26:5; OdeSol 11:5) B 5:14; 6:3 (ambos Is 50:7). (Em oposição a <span class=\"greek\">γάλα</span>) <span class=\"greek\">στερεὰ</span> <span class=\"greek\">τροφή</span>, alimento sólido (Theophr., CP 3, 16; Diod S 2, 4, 5; Epict. 2, 16, 39; Lucian, Lexiph. 23) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:12</a>, 14.</p><p class=\"entry-text\">② extensão figurada de 1, acerca do caráter humano (Hom. e outros), firme, constante (Diog. L. 2, 132, acerca de atletas; Quint. Smyrn. [c. 400 d.C.] 5, 597; 9, 508 Zimmermann [1891] <span class=\"greek\">στερεῇ</span> <span class=\"greek\">φρενί</span> = com mente constante) <span class=\"greek\">στερεοὶ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">πίστει</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 5:9</a> (<span class=\"greek\">ἑδραῖοι</span> P72).—DELG s.v. 2 <span class=\"greek\">στεῖρα</span>, B <span class=\"greek\">στερεός</span>; Frisk s.v. <span class=\"greek\">στερεός</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0331-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στερεόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στερεόω</span> (<span class=\"greek\">στερεός</span>), futuro, 2 pessoa do singular <span class=\"greek\">στερεώσεις</span>; 1 aoristo <span class=\"greek\">ἐστερέωσα</span>. Na voz passiva: imperfeito <span class=\"greek\">ἐστερεούμην</span>; futuro, 3 pessoa do singular <span class=\"greek\">στερεωθήσεται</span> LXX; 1 aoristo <span class=\"greek\">ἐστερεώθην</span>; particípio perfeito feminino <span class=\"greek\">ἐστερεωμένη</span> 1 Km 6:18 (X. e outros; LXX; En 103:15).</p><p class=\"entry-text\">① tornar fisicamente firme, fortalecer, firmar; literalmente, acerca de membros privados de força, na voz passiva, ser fortalecido, tornar-se forte: <span class=\"greek\">ἐστερεώθησαν</span> <span class=\"greek\">αἱ</span> <span class=\"greek\">βάσεις</span> <span class=\"greek\">αὐτοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:7</a> (X., De Re Equ. 4, 3 <span class=\"greek\">τοὺς</span> <span class=\"greek\">πόδας</span>; Hippocr., Epid. 2, 3, 17 ed. Littré; V p. 118 <span class=\"greek\">τὰ</span> <span class=\"greek\">ὀστέα</span>; Hippiatr. II 82, 1). Com base nessa passagem, a voz ativa é utilizada em referência ao mesmo ato de cura: <span class=\"greek\">τοῦτον</span> <span class=\"greek\">ἐστερέωσεν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομα</span>, o nome (de Cristo) fortaleceu este homem, v. 16.</p><p class=\"entry-text\">② fazer alguém tornar-se mais firme em questões como convicção ou compromisso, fortalecer, extensão figurada de 1 (1 Km 2:1 <span class=\"greek\">ἡ</span> <span class=\"greek\">καρδία</span>); na voz passiva, <span class=\"greek\">αἱ</span> <span class=\"greek\">ἐκκλησίαι</span> <span class=\"greek\">ἐστερεοῦντο</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">πίστει</span>, as congregações eram continuamente (imperfeito) fortalecidas na fé, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:5</a>.—DELG s.v. 2 <span class=\"greek\">στεῖρα</span>, B <span class=\"greek\">στερεός</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0331-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στερέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στερέω</span>, futuro, 3 pessoa do singular <span class=\"greek\">στερήσει</span> Ps 83:12; 1 aoristo <span class=\"greek\">ἐστέρησα</span>. Voz passiva: futuro, 3 pessoa do singular <span class=\"greek\">στερηθήσει</span> (ApcMos 26), 3 pessoa do plural <span class=\"greek\">στερηθήσονται</span> 4 Macc 4:7; 1 aoristo <span class=\"greek\">ἐστερήθην</span> LXX; perfeito, 3 pessoa do plural <span class=\"greek\">ἐστέρηνται</span> 3 Macc 1:12 (Hom. e outros; pap, LXX; Jos., C. Ap. 2, 277, Ant. 16, 93), privar <span class=\"greek\">τινά</span> <span class=\"greek\">τινος</span> alguém de alguma coisa, B 13:4 (Gen 48:11).—DELG s.v. <span class=\"greek\">στέρομαι</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0331-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στερέωμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στερέωμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">στερεόω</span>; em sentidos variados de algo sólido: Aristot. e outros; Herm. Wr. 514, 12 Sc.; PGM 4, 1210; IDefixWünsch 4, 22; LXX, En; TestSol 20:12, 17; TestAbr B 12 p. 116, 12 [Stone p. 80]; TestJob 8:1; ApcMos; Mel. 82, 615; Ath. 24, 5), originalmente ‘a parte sólida’.</p><p class=\"entry-text\">① o céu como estrutura de sustentação, firmamento (Gen 1:6ff; En 18:2; Philo, Op. M. 36; TestNapht 3:4; IDefixAudollent 242, 8 [século III d.C.]) 1 Cl 27:7 (Ps 18:2).</p><p class=\"entry-text\">② estado ou condição de compromisso firme, firmeza, constância, <span class=\"greek\">τῆς</span> <span class=\"greek\">πίστεως</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:5</a> (cf. 1 Macc 9:14 [sentido militar]).—DELG s.v. <span class=\"greek\">στεῖρα</span>, B <span class=\"greek\">στερεός</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0331-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Στεφανᾶς, ᾶ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino; nome próprio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Στεφανᾶς</span>, <span class=\"greek\">ᾶ</span>, <span class=\"greek\">ὁ</span> (CIG II, 3378; Sb 361, 10 [no genitivo <span class=\"greek\">Στεφανᾶτος</span>].—Forma abreviada de <span class=\"greek\">Στεφανηφόρος</span>? ou desenvolvimento de <span class=\"greek\">Στέφανος</span>? B-D-F §125, 1; Rob. 173; 255; W-S. §16, 9; AFick2-FBechtel, Griech. Personennamen 1894, 253f), Estéfanas, membro da igreja de Corinto que, com sua casa, foi batizado pelo próprio Paulo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:16</a>, como as ‘primícias da Acaia’, 16:15. Segundo o v. 17, encontrava-se com Fortunato e Acaico na companhia de Paulo em Éfeso. Juntamente com outros presbíteros de Corinto, dirige uma solicitação a Paulo, AcPlCor 1:1. Ver também subscrição de 1 Cor.—LGPN I. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0331-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Στέφανος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino; nome próprio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Στέφανος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (desde Andocides 1, 18; Pla, Meno 94c; Demosth.; ins, pap; Jos., Bell. 2, 228), nome frequentemente encontrado, Estêvão, um dos sete ‘auxiliares’ em Jerusalém. Atos relata que realizou milagres e ganhou especial destaque como pregador. Divergências religiosas com certas sinagogas (ver <span class=\"greek\">Λιβερτίνος</span>) levaram-no perante o Sinédrio, onde proferiu um discurso que incitou a audiência a tal ponto que o apedrejaram na presença de Saulo (Paulo), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:5</a>, 8f; 7:1 v.l., 59; 8:2; 11:19; 22:20.—KPahncke, StKr 85, 1912, 1–38; WMundle, ZNW 20, 1921, 133–47; EMeyer III 154ff; JRopes, StKr 102, 1930, 307–15; AFridrichsen, Le Monde oriental 25, ’32, 44–52; RSchumacher, Der Diakon Stephanus 1910; MSimon, St. Stephen and the Hellenists in the Primitive Church ’58; JBihler, D. Stephanusgeschichte etc. ’63; CBarrett, Stephen and the Son of Man, EHaenchen Festschr. ’64, 32–38; MScharlemann, Stephen, a Singular Saint ’68; MHengel, ZTK 72, ’75, 151–206.—Kl. Pauly V 360f [no. 11]; BHHW III 1864f; Haenchen ad loc.—LGPN I. M-M. EDNT.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0331-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στέφανος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στέφανος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (ver o verbete seguinte; Hom.+).</p><p class=\"entry-text\">① grinalda feita de folhagem, ou concebida para assemelhar-se a folhagem, usada por alguém de posição elevada ou muito estimado, grinalda, coroa. Hs 8, 2, 1ab. A ‘coroa de espinhos’ de Jesus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:2</a>, 5; GPt 3:8 (sobre a coroação com espinhos e a zombaria contra Jesus, ver FCumont, AnalBoll 16, 1897, 3ff; LParmentier, Le roi des Saturnales: RevPhilol, n.s. 21, 1897, 143ff; PWendland, Jesus als Saturnalienkönig: Her 33, 1898, 175–79; WPaton, ZNW 2, 1901, 339–41; SReinach, Le roi supplicié: L’Anthropologie 33, 1902, 621ff; HReich, D. König m. der Dornenkrone 1905 [=NJklA 13, 1904, 705–33]; HVollmer, ZNW 6, 1905, 194–98, 8, 1907, 320f, Jesus u. das Sacäenopfer 1905; KLübeck, Die Dornenkrönung Christi 1906; JGeffcken, Her 41, 1906, 220–29; KKastner, Christi Dornenkrönung u. Verspottung durch die röm. Soldateska: BZ 6, 1908, 378–92, ibid. 9, 1911, 56; TBirt, PJ 137,1909, 92–104; HAllroggen, Die Verspottung Christi: ThGl 1, 1909, 689–708; HZimmern, Zum Streit um die Christusmythe 1910, 38ff, Verh. d. Sächs. Ges. d. W., phil.-Hist. Kl. 70, 5, 1918, Pauly-W. segunda série II 1, 208; LRadermacher, ARW 28, 1930, 31–35; RDelbrueck, Antiquarisches zu den Verspottungen Jesu: ZNW 41, ’42, 124–45). Quanto à grinalda concedida ao vencedor de uma competição atlética (Aelian, VH 9, 31; TestJob 4:10; Tat. 11, 1; 23, 1; sobre o contexto sociocultural, ver APapathomas, NTS 43, ’97, 225–33), cf. a imagem referente a uma recompensa celestial, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:25</a>; 2 Cl 7:3 (ver 3 abaixo).—Além do reconhecimento concedido a atletas e vencedores de diversos tipos de competição, no mundo greco-romano a outorga de uma coroa ou grinalda significava apreço por contribuições excepcionais ao Estado ou aos grupos que o compunham (ver os índices dos corpora epigráficos e a bibliografia citada no fim deste artigo; cf. SEG XXXII, 809, 3f). Os agraciados eram geralmente funcionários públicos ou pessoas de espírito cívico que prestavam serviços às próprias expensas (ver New Docs 7, 240 e os verbetes iniciados por <span class=\"greek\">λειτουργ</span>-; ver MBlech abaixo). No Apocalipse, a coroa (de ouro) é usada por seres de elevada posição (seres divinos com coroa de ouro: PGM 4, 698; 1027; o sumo sacerdote com o <span class=\"greek\">στ</span>. <span class=\"greek\">χρύσεος</span>: Jos., Ant. 3, 172; o rei, 17, 197; MParca, ASP 31, ’91, 41–44, sobre a coroa radiante na Antiguidade [cf. PKöln VI, 245, 14]): pelos 24 anciãos, 4:4, 10 (talvez as coroas ou grinaldas de ouro dos 24 anciãos simplesmente pertençam aos adornos habituais daqueles que acompanham uma figura divina. Cf. Athen. 5, 197f, a procissão triunfal de Dioniso com 40 <span class=\"greek\">σάτυροι</span> usando grinaldas douradas; também toda a fantástica procissão ali descrita; ver ainda MGuarducci, Epigraphica 35, ’73, 7–23; 39, ’77, 140–42); também pelo Ser Humano (Filho do Homem), 14:14 (que em 19:12 usa o verdadeiro adorno de cabeça de um governante [ver <span class=\"greek\">διάδημα</span>]. Mas ver 2 Km 12:30; 1 Ch 20:2; SSol 3:11); ver também 6:2; 9:7; 12:1 (<span class=\"greek\">στεφ</span>. <span class=\"greek\">ἀστέρων</span> <span class=\"greek\">δώδεκα</span>, ver Boll. 99). Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:25</a>, <span class=\"greek\">ς</span>. cumpre dupla função: primeiro refere-se a uma coroa terrena, depois a uma celestial (cf. 2 Cl 7:3 e ver 3 abaixo).—Ignácio se refere metaforicamente ao presbitério como <span class=\"greek\">ἀξιόπλοκος</span> <span class=\"greek\">πνευματικὸς</span> <span class=\"greek\">στέφανος</span>, grinalda espiritual dignamente entretecida, IMg 13:1; mas essa passagem pertence igualmente à acepção 2.</p><p class=\"entry-text\">② aquilo que serve de adorno ou motivo de orgulho, ornamento, orgulho, extensão figurada de 1 (Lycurgus 50, acerca de helenos valorosos que morreram em defesa da liberdade e cujas ‘almas são a <span class=\"greek\">ς</span>. da pátria’; Hom., Epigr. 13, 1 <span class=\"greek\">ἀνδρὸς</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">στέφανος</span> <span class=\"greek\">παῖδες</span>; Eur., Iphig. Aul. 193 <span class=\"greek\">Αἴας</span> <span class=\"greek\">τᾶς</span> <span class=\"greek\">Σαλαμῖνος</span> <span class=\"greek\">στέφ</span>.; Pr 12:4; 17:6.—Expressão indicativa de terno amor: HSwoboda e outros, Denkmäler aus Lykaonien etc. 1935 p. 78, no. 168), acerca dos filipenses, <span class=\"greek\">χαρὰ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">στέφανός</span> <span class=\"greek\">μου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:1</a>. (<span class=\"greek\">χαρὰ</span> <span class=\"greek\">ἢ</span>) <span class=\"greek\">στέφανος</span> <span class=\"greek\">καυχήσεως</span>, prêmio de que se pode orgulhar (Goodsp.; cf. Pr 16:31), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:19</a>. Ver IMg 13:1 em 1 acima, ao fim.</p><p class=\"entry-text\">③ prêmio ou recompensa por serviço ou conduta excepcional, prêmio, recompensa, figuradamente (LXX; ApcEsdr 6:17, 21 p. 31, 26 e 31 Tdf.; como símbolo de vitória ANock, ClR 38, 1924, 108 n. 11). Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:25</a> (com referência à incorruptibilidade) e 2 Cl 7:3 (ver 1 acima), a referência à coroa ou grinalda ainda se faz sentir fortemente; nas passagens seguintes, porém, a imagem da grinalda torna-se cada vez menos nítida, sem perder seu significado principal como símbolo de mérito excepcional (Ael. Aristid. 27, 36 K.=16 p. 397 D.: <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀθανάτων</span> <span class=\"greek\">στ</span>.; PSI 405, 3 [século III a.C.]; Danker, Benefactor 468–71). Genitivo objetivo: <span class=\"greek\">τ</span>. <span class=\"greek\">δικαιοσύνης</span>, pela justiça (o reconhecimento da retidão é tema recorrente nos decretos greco-romanos; ver <span class=\"greek\">δικαιοσύνη</span> 3a; sobre o caráter excepcional pressuposto daquele que usa uma coroa, ver LDeubner, De incubatione capitula duo, 1899, 26) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:8</a> (sobre recompensa póstuma, ver New Docs 2, 50; cf. Soph., Phil. 1421f, acerca da glória após o sofrimento). Com genitivo epexegético (este é o sentido de <span class=\"greek\">στ</span>. <span class=\"greek\">δικαιοσύνης</span> EpArist 280; TestLevi 8:2), <span class=\"greek\">ὁ</span> <span class=\"greek\">στέφ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ζωῆς</span> (ver <span class=\"greek\">ζωή</span> 2b<span class=\"greek\">β</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:10</a>; cf. 3:11; <span class=\"greek\">ὁ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀφθαρσίας</span> <span class=\"greek\">στ</span>. MPol 17:1; 19:2; <span class=\"greek\">ὁ</span> <span class=\"greek\">ἀμαράντινος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">δόξης</span> <span class=\"greek\">στ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 5:4</a> (cf. Jer 13:18 <span class=\"greek\">στ</span>. <span class=\"greek\">δόξης</span>; La 2:15; cf. 1QS 4:7; 1QH 9:25; <span class=\"greek\">τῆς</span> <span class=\"greek\">βασιλείας</span> <span class=\"greek\">στ</span>. Hippol., Ref. 9, 17, 4).—<span class=\"greek\">ἐλευθέριος</span> <span class=\"greek\">στ</span>. AcPl Ha 2, 31.—MBlech, Studien zum Kranz bei den Griechen 1982 (bibliografia).—Schürer III/1 103f, n. 60 (bibliografia). Pauly-W. XI 1588–1607; Kl. Pauly III 324f; BHHW II 999f.—New Docs 2, 50. DELG s.v. <span class=\"greek\">στέφω</span>. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0331-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στεφανόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στεφανόω</span> (<span class=\"greek\">στέφανος</span>), futuro, 2 pessoa singular <span class=\"greek\">στεφανώσει</span> Ps 5:13 Aq., Sym.; aoristo 1 <span class=\"greek\">ἐστεφάνωσα</span>. Voz passiva: futuro, 3 pessoa singular <span class=\"greek\">στεφανωθήσεται</span> 3 Macc 3:28; aoristo 1 <span class=\"greek\">ἐστεφανώθην</span>; particípio perfeito <span class=\"greek\">ἐστεφανωμένος</span> (Hom.+).</p><p class=\"entry-text\">① circundar a cabeça de alguém com folhagem ornamental, adornar com uma grinalda, coroar <span class=\"greek\">τινά</span> (ver <span class=\"greek\">στέφανος</span> 1), alguém (Diod S 20, 94, 5) Hs 8, 2, 1. O vencedor de uma competição atlética (que recebia uma grinalda de alguma variedade botânica), na voz passiva (Pind., O. 4, 14; Hdt. 8, 59; PCairZen 60, 7 [257 a.C.]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:5</a>; 2 Cl 7:1; cf. 7:2, 3; 20:2 (onde 2 Cl passa à coroação do vencedor na competição imortal. Ver o hino a Serápis IG XI/4, 1299, 9f [c. 200 a.C.] <span class=\"greek\">διὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">εὐσέβειαν</span> <span class=\"greek\">ἐστεφανώθη</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>). Hs 8, 3, 6; 8, 4, 6.—Um dos dois bodes no grande Dia da Expiação (Lev 16:5ff) é chamado <span class=\"greek\">ἐστεφανωμένος</span> e considerado um tipo de Cristo, B 7:9.</p><p class=\"entry-text\">② reconhecer serviço ou desempenho notável mediante uma recompensa, honrar, recompensar, coroar, extensão figurada de 1 (Pind., Eur. e outros.—Cebes 22, 1 <span class=\"greek\">στ</span>. <span class=\"greek\">δυνάμει</span>; 23, 4) <span class=\"greek\">δόξῃ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τιμῇ</span> <span class=\"greek\">ἐστεφάνωσας</span> <span class=\"greek\">αὐτόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:7</a> (Ps 8:6); cf. v. 9 (Windisch, Hdb. ad loc. [bibliografia]). Acerca do mártir Policarpo, <span class=\"greek\">ἐστεφανωμένος</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀφθαρσίας</span> <span class=\"greek\">στέφανον</span> MPol 17:1 (Diod S 16, 13, 1 <span class=\"greek\">στεφάνοις</span> <span class=\"greek\">ἐστεφανωμένους</span>; cf. Iren. 5, 29, 1 [Harv. II 404]). Cf. 2 Cl 20:2 (ver 1 acima). Construção pregnante: <span class=\"greek\">στεφανωθεὶς</span> <span class=\"greek\">κατ</span>’ <span class=\"greek\">αὐτῆς</span>, coroado vencedor (na luta) contra ela (isto é, o desejo maligno), Hm 12, 2, 5.—Os termos <span class=\"greek\">τιμή</span> e <span class=\"greek\">τιμάω</span> (ver respectivos verbetes) estão tão intimamente associados à concessão de grinalda ou coroa que seu emprego sugere os tipos de qualidades ou feitos que convidam a esse reconhecimento público (ver MBlech, Studien zum Kranz bei den Griechen ’82, 161; bibliografia xvii–xxxiii).—DELG s.v. <span class=\"greek\">στέφω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0331-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στῆθος, ους, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στῆθος</span>, <span class=\"greek\">ους</span>, <span class=\"greek\">τό</span> (Hom.+), peito, tórax <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.15.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 15:6</a>; Hv 1, 4, 2 (Leutzsch, Hermas 393 n. 132). <span class=\"greek\">ἀναπεσεῖν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">στ</span>. <span class=\"greek\">τινος</span> (<span class=\"greek\">ἀναπίπτειν</span> 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.25\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:25</a>; 21:20. <span class=\"greek\">τύπτειν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">στῆθος</span> (<span class=\"greek\">αὐτοῦ</span>), bater no próprio peito como sinal de tristeza, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:13</a> (variante de leitura <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">στῆθος</span>); 23:48. Também <span class=\"greek\">κόπτεσθαι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">στ</span>. (<span class=\"greek\">κόπτω</span> 2) GPt 8:28. Como sede da vida interior (já em Alcaeus [séculos VII/VI a.C.] Fgm. 283, 3 Treu, p. 6 ln. 3]; Iambl., Vi. Pyth. 35, 252) 2 Cl 19:2.—B. 24. DELG. M-M. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0331-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στήκω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στήκω</span> (encontrado primeiramente no NT; na LXX, somente como variante de leitura não confiável [ADebrunner, GGA 1926, 146f], mas ocorre também em TestSol; TestJob 26:6; Kaibel 970; Hippiatr. 69, 2 e 4 p. 269, 16; 270, 16; PGM 4, 923; 36, 273. Formação tardia a partir de <span class=\"greek\">ἕστηκα</span>, o perfeito de <span class=\"greek\">ἵστημι</span>, e empregado ao lado deste; ver B-D-F §73; Mlt-H. 220; 259.—<span class=\"greek\">εστηκεν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.44\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:44</a> provavelmente é o perfeito de <span class=\"greek\">ἵστημι</span>, quer se escreva <span class=\"greek\">ἕστ</span>. quer <span class=\"greek\">ἔστ</span>.; ver EAbbott, The Authorship of the 4th Gosp. and Other Critical Essays, 1888, 286–93; B-D-F §14; 73; 97, 1; diferentemente Rob. 224, seguindo W-H.; ver também Mlt-H. 100. Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:4</a>, provavelmente deve-se preferir o imperfeito <span class=\"greek\">ἔστηκεν</span> ao perfeito <span class=\"greek\">ἕστ</span>.).</p><p class=\"entry-text\">① estar na posição ereta, estar de pé, permanecer de pé, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:25</a>; <span class=\"greek\">ἔξω</span> <span class=\"greek\">στ</span>., permanecer do lado de fora, 3:31. <span class=\"greek\">μέσος</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">στήκει</span>, está alguém de pé no meio de vós, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.26\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:26</a>, variante de leitura. <span class=\"greek\">ὁ</span> <span class=\"greek\">δράκων</span> <span class=\"greek\">ἔστηκεν</span> <span class=\"greek\">ἐνώπιον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γυναικός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:4</a>, variante de leitura (ver acima).</p><p class=\"entry-text\">② manter-se firmemente comprometido com uma convicção ou crença, extensão figurada de 1: manter-se firme, ser constante; <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span>, em algo: <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">πίστει</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:13</a>; <span class=\"greek\">ἐν</span> <span class=\"greek\">κυρίῳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 3:8</a>; <span class=\"greek\">ἐν</span> <span class=\"greek\">ἑνὶ</span> <span class=\"greek\">πνεύματι</span>, em um só espírito, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:27</a>. <span class=\"greek\">τῷ</span> <span class=\"greek\">ἰδίῳ</span> <span class=\"greek\">κυρίῳ</span> <span class=\"greek\">στήκειν</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">πίπτειν</span>, ficar de pé ou cair para vantagem ou desvantagem de seu próprio senhor, ou ser assunto de seu próprio senhor se ele permanece de pé ou cai, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:4</a>. Absolutamente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:1</a> (deve-se subentender ‘na liberdade’).—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0331-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στήλη, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στήλη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (Hom. e outros; ins, pap, LXX, Philo; Jos., Ant. 14, 188; Just., D. 86, 2; empréstimo na linguagem rabínica), bloco de pedra ou coluna comemorativa, monumento, coluna; desde o tempo de Homero, gravado com inscrições e usado como marcador de sepultura ou para comemorar acontecimentos, promulgar decretos, reconhecer feitos pessoais (frequentemente além da concessão de uma grinalda, ver <span class=\"greek\">στέφανος</span> 3) e coisas semelhantes; com <span class=\"greek\">τάφοι</span> <span class=\"greek\">νεκρῶν</span>, lápides funerárias, IPhld 6:1. <span class=\"greek\">στ</span>. <span class=\"greek\">ἁλός</span>, coluna de sal (Gen 19:26) 1 Cl 11:2 (irônico, como indica a expressão subsequente <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">γνωστὸν</span> <span class=\"greek\">εἶναι</span> <span class=\"greek\">πᾶσιν</span> [sinônimo formular de uma oração final comum em decretos honoríficos, <span class=\"greek\">ἵνα</span>/<span class=\"greek\">ὅπως</span> <span class=\"greek\">πάντες</span> <span class=\"greek\">γινώσκωσιν</span> e variantes, p.ex. SIG 656, 37; 695, 74], mas aqui expressando condenação em lugar de elogio; ver <span class=\"greek\">γνωστός</span> 2).—TWujewski, Anatolian Sepulchral Stelae in Roman Times ’91. Pauly-W. II/3, 2307–25; 4, 428–34; Kl. Pauly V 255f; BHHW III 1678f. DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0331-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στηριγμός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στηριγμός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">στηρίζω</span>; Aristot. e outros, no sentido de ‘imobilidade’.—Is 3:1 Sym. [LXX; En 18:5; TestJud 15:3, 6 têm <span class=\"greek\">στήριγμα</span>]), na literatura aqui considerada, apenas figuradamente.</p><p class=\"entry-text\">① estado de segurança, posição segura; <span class=\"greek\">τοῦ</span> <span class=\"greek\">στ</span>. <span class=\"greek\">ἐκπίπτειν</span>, perder o apoio firme, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:17</a> (REB: ponto de apoio seguro; NRSV: estabilidade). Mas o termo <span class=\"greek\">ς</span>. também pode ser compreendido no sentido de</p><p class=\"entry-text\">② compromisso firme com convicção ou crença, firmeza, constância; <span class=\"greek\">τοῦ</span> <span class=\"greek\">στ</span>. <span class=\"greek\">ἐκπίπτειν</span>, perder a firmeza de seu compromisso, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:17</a>.—DELG s.v. <span class=\"greek\">στηρίζω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0331-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στηρίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στηρίζω</span> (Hom.+; também OGI 612, 8; 769, 11; InsGolanHeights no. 11* linha 11; PSI 452, 3), futuro <span class=\"greek\">στηρίξω</span> (ao lado de <span class=\"greek\">στηρίσω</span>—B-D-F §71; W-S. §13, 4; Mlt-H. 259; Rob. 1219—e <span class=\"greek\">στηριῶ</span> [ver Ezk 14:8; Sir 6:37]); aoristo 1 <span class=\"greek\">ἐστήριξα</span> (t.r.) e <span class=\"greek\">ἐστήρισα</span> (B-D-F §71; W-S. § 13, 4; Mlt-H.; e Rob., como acima). Voz passiva: futuro, 3 pessoa singular <span class=\"greek\">στηριχθήσεται</span> Sir 15:4 e <span class=\"greek\">στηρισθήσεται</span> Sir 15:4 variante de leitura; aoristo 1 <span class=\"greek\">ἐστηρίχθην</span>; perfeito <span class=\"greek\">ἐστήριγμαι</span>, infinitivo <span class=\"greek\">ἐστηρίχθαι</span> (LXX, Just.) e <span class=\"greek\">ἐστηρίσθαι</span> 1 Km 26:19.</p><p class=\"entry-text\">① fixar firmemente em um lugar, estabelecer, firmar, sustentar, literalmente, <span class=\"greek\">τὶ</span>, algo: <span class=\"greek\">τοὺς</span> <span class=\"greek\">οὐρανούς</span> 1 Cl 33:3 (<span class=\"greek\">στ</span>. acerca da criação do mundo: Arat., Phaen. 10; Orphica, Fgm. 170, 3; Mel.; ver Hippol, Ref. 6, 32, 2 [com <span class=\"greek\">μορφόω</span>]). Voz passiva, acerca de uma cidade, estar bem estabelecida, Ox 1, 17–18 (GTh 32). Acerca de um abismo, <span class=\"greek\">ἐστήρικται</span>, foi fixado, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:26</a> (cf. Gen 28:12 <span class=\"greek\">κλίμαξ</span> <span class=\"greek\">ἐστηριγμένη</span>; En 24:2; ParJer 9:17 <span class=\"greek\">τὸ</span> <span class=\"greek\">δένδρον</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">στηριχθέν</span>).</p><p class=\"entry-text\">② tornar alguém interiormente firme ou comprometido, confirmar, estabelecer, fortalecer, extensão figurada de 1 (Apollon. Rhod. 4, 816, acerca de ódio; Appian, Bell. Civ. 1, 98 <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀρχήν</span>; Ps 50:14; Sir 3:9; 1 Macc 14:14), com acusativo, <span class=\"greek\">οὐ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἑστῶτα</span> <span class=\"greek\">στηρίζειν</span> <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πίπτοντα</span> 2 Cl 2:6 (ver Sir 13:21).—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 3:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 5:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:2</a>. Na voz passiva (Iren. 1, 2, 4 [Harv. I 19, 1]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:11</a>. <span class=\"greek\">τὴν</span> <span class=\"greek\">καρδίαν</span> <span class=\"greek\">τινός</span> (Judg 19:5, 8; Sir 6:37; 22:16) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:8</a>; com segundo acusativo, <span class=\"greek\">στ</span>. <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">καρδίας</span> <span class=\"greek\">ἀμέμπτους</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 3:13</a> (ver Rtzst., Erlösungsmyst. 147, 3). <span class=\"greek\">τινὰ</span> <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span>, alguém em algo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:17</a>; IPhld inscrição. Voz passiva, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:12</a>. <span class=\"greek\">τινά</span> <span class=\"greek\">τινι</span>, fortalecer alguém com alguma coisa, 1 Cl 18:12 (Ps 50:14). <span class=\"greek\">τινὶ</span> <span class=\"greek\">στ</span>. <span class=\"greek\">ἑαυτὸν</span> <span class=\"greek\">εἴς</span> <span class=\"greek\">τι</span>, fortalecer-se com alguma coisa a fim de fazer algo, 13:3; <span class=\"greek\">στ</span>. <span class=\"greek\">τινί</span>, estabelecer (alguma coisa) por meio de algo, 8:5. <span class=\"greek\">ἐὰν</span> <span class=\"greek\">ἐστηριγμένη</span> <span class=\"greek\">ᾖ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">διάνοια</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">πιστῶς</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span>, se nossa mente estiver firmemente fixada em Deus pela fé, 35:5. <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">κίνδυνον</span>, <span class=\"greek\">ὑμεῖς</span> <span class=\"greek\">ἐστηριγμένοι</span>, eu estou em perigo, vós estais em segurança, IEph 12:1.—Em sentido relacionado, mas conservando mais evidentemente a imagem de algo fixado, estar determinado a alcançar um objetivo, resolver: hebraísmo <span class=\"greek\">στηρίζειν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πρόσωπον</span>, firmar o rosto (Ezk 6:2; 13:17; 14:8; 15:7), para indicar firmeza de propósito (ver Jer 21:10; cf. nosso ‘cerrar o maxilar’), seguido do genitivo do infinitivo com artigo (B-D-F §400, 7; Rob. 1068) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.51\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:51</a> (ver <span class=\"greek\">πρόσωπον</span> 1b e, sobre 9:51–19:27, HConzelmann, The Theology of St. Luke, tradução de GBuswell, ’60, especialmente 60–73).—DELG. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0331-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στιβάζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στιβάζω</span> (<span class=\"greek\">στιβάς</span>; exemplos em WCrönert, GGA 1909, 656), literalmente ‘colocar sobre um leito’, depois, acerca da deposição de algo para utilização futura, armazenar <span class=\"greek\">εἰς</span> <span class=\"greek\">ἀποθήκην</span> <span class=\"greek\">οἶνον</span>, vinho na adega, Hm 11:15.—DELG s.v. <span class=\"greek\">στείβω</span> A 3.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0331-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στιβαρός, ά, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στιβαρός</span>, <span class=\"greek\">ά</span>, <span class=\"greek\">όν</span> (provavelmente cognato de <span class=\"greek\">στείβω</span> ‘pisar’; Hom. e outros; IAndrosIsis 170; Ezk 3:6; Herm. Wr II, 2 [Sc. 134]; Jos., Bell. 6, 161; 293; SibOr Fgm. 3, 39), robusto, vigoroso (com <span class=\"greek\">ἰσχυρός</span>), <span class=\"greek\">δύναμις</span> Hm 5, 2, 3.—DELG s.v. <span class=\"greek\">στείβω</span> A 4.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0331-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στιβάς, άδος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">στιβάς</span>, <span class=\"greek\">άδος</span>, <span class=\"greek\">ἡ</span> (Eur., Hdt. e outros; ins, pap, acerca de um tipo de cama ou colchão feito de palha, junco, caniços, folhas etc.), no único lugar em que ocorre na literatura aqui considerada (não se encontra na LXX, EpArist nem Philo, mas é empréstimo na linguagem rabínica), evidentemente significa folhas, ramos folhosos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:8</a> (sobre a grafia <span class=\"greek\">στοιβάς</span> no t.r., ver W-S. §5, 16; Mlt-H. 76).—DELG s.v. <span class=\"greek\">στείβω</span> A 3. M-M.</p></section></article>"};
